def _envvar_names(self) -> tuple[str, ...]:
    """The non-empty names in :attr:`envvar`, which are the ones
    :meth:`resolve_envvar_value` can read.
    """
    if not self.envvar:
        return ()

    if isinstance(self.envvar, str):
        return (self.envvar,)

    return tuple(str(d) for d in self.envvar if d)

def get_error_hint(self, ctx: Context | None) -> str:
    result = super().get_error_hint(ctx)
    envvars = self._envvar_names()
    if self.show_envvar and envvars:
